package org.marketreview.nativeapp;
import org.json.*;
import android.content.Context;
import java.nio.file.*;
import java.io.File;
import java.nio.charset.StandardCharsets;
final class PersonMethodChecks {
 static int count;
 static void check(boolean yes,String why){count++;if(!yes)throw new AssertionError(why);}
 interface Throwing {void run()throws Exception;}
 static void rejects(Throwing fn,String why)throws Exception{boolean fail=false;try{fn.run();}catch(Exception e){fail=true;}check(fail,why);}
 static JSONObject subject(String entity,String id)throws Exception{return PersonMethodModel.seal(new JSONObject().put("kind","subjects").put("entityId",entity).put("id",id).put("parentId","").put("savedAt","").put("subjectType","person").put("displayName","同名作者").put("platform","公开出处").put("profileUrl","https://example.org/person").put("aliases",new JSONArray()).put("description","自述收益是营销主张").put("identityStatus","unverified").put("identityBasis",""));}
 static JSONObject method(JSONObject s,JSONObject source)throws Exception{JSONObject r=new JSONObject().put("kind","methods").put("entityId","m").put("id","m@1").put("parentId","").put("savedAt","").put("subjectId",s.getString("entityId")).put("subjectRef",PersonMethodModel.version("person-method","subjects",s.getString("id"),s)).put("title","人工方法").put("versionLabel","初稿").put("conditions","条件待核验").put("steps","步骤").put("evidenceQuote","研究😀").put("counterexamples","未找到反例，不代表没有").put("invalidations","边界").put("interpretation","人工解释").put("sourceRefs",new JSONArray().put(PersonMethodModel.version("person-method","sources",source.getString("id"),source)));return PersonMethodModel.seal(r);}
 static JSONObject fixture(String path)throws Exception{return PersonMethodModel.decode(new String(Files.readAllBytes(Paths.get(path)),StandardCharsets.UTF_8));}
 static void runModel(JSONObject fixture)throws Exception{rejects(()->PersonMethodModel.decode("{expertChannels:[]}"),"unquoted JSON rejected");rejects(()->PersonMethodModel.decode("{\"expertChannels\":[],}"),"trailing comma rejected");rejects(()->PersonMethodModel.hash(new JSONObject().put("unsafe",9007199254740992d)),"unsafe numeric original rejected rather than rounded");rejects(()->PersonMethodModel.decode("{\"schema\":\"person-method/v99\",\"expertChannels\":[]}"),"future schema no legacy fallback");JSONObject s=fixture.getJSONArray("subjects").getJSONObject(0),source=fixture.getJSONArray("sources").getJSONObject(0);check(source.getString("text").endsWith("原始转写尾部"),"full tail");check(source.getJSONObject("legacyOriginal").has("commentData"),"comments archive");check(source.toString().getBytes(StandardCharsets.UTF_8).length>2*1024*1024,"long row fixture remains >2MiB");check(s.getString("identityStatus").equals("unverified"),"no automatic identity");JSONObject conflicting=new JSONObject(s.toString()).put("description","conflict");conflicting=PersonMethodModel.seal(conflicting);JSONObject conflictImport=PersonMethodModel.empty().put("subjects",new JSONArray().put(conflicting));check(PersonMethodModel.preview(conflictImport,fixture).getJSONArray("conflicts").length()==1,"same-ID conflict explicit keep-existing preview");JSONObject m=method(s,source);check(PersonMethodModel.canonical(m).equals(PersonMethodModel.canonical(fixture.getJSONArray("methods").getJSONObject(0))),"Qt full-record fingerprints identical");check(m.getJSONObject("assessment").getString("status").equals("fields_complete_not_validated"),"fields complete not validated");check(!m.getJSONObject("assessment").getBoolean("methodValidated"),"no confirmed effectiveness");JSONObject bare=PersonMethodModel.version("person-method","sources",source.getString("id"),source);bare.remove("originalRecord");rejects(()->PersonMethodModel.validateVersion(bare),"bare ref rejected");JSONObject bad=new JSONObject(m.toString());bad.getJSONObject("assessment").put("authorConfirmed",true);rejects(()->PersonMethodModel.validate(bad),"confirmed author rejected");JSONObject missing=new JSONObject().put("tables",new JSONObject().put("expertChannels",new JSONArray().put(new JSONObject().put("displayName","same").put("platform","old"))));rejects(()->PersonMethodModel.decode(missing.toString()),"missing explicit identity rejected");JSONObject old=new JSONObject().put("channelKey","same-key").put("subjectType","book").put("displayName","同名").put("platform","publisher").put("observations",new JSONArray().put(new JSONObject().put("id",42).put("title","old").put("content","完整原文").put("confidence",1).put("evidenceLevel","primary").put("unknown","keep")));JSONObject official=new JSONObject().put("version",1).put("tables",new JSONObject().put("expertChannels",new JSONArray().put(old)));JSONObject decoded=PersonMethodModel.decode(official.toString());check(decoded.getJSONArray("subjects").getJSONObject(0).getString("identityStatus").equals("unverified"),"official old confidence not reviewed");check(decoded.getJSONArray("sources").getJSONObject(0).getJSONObject("legacyOriginal").getString("unknown").equals("keep"),"old unknown field retained");}
 static String run(Context c,String fixtureText)throws Exception{count=0;JSONObject fixture=PersonMethodModel.decode(fixtureText);runModel(fixture);String name="person-method-focused-"+System.nanoTime()+".sqlite";PersonMethodStore s=new PersonMethodStore(c,name);try{JSONObject empty=s.backup();PersonMethodModel.preview(fixture,empty);check(PersonMethodModel.canonical(empty).equals(PersonMethodModel.canonical(s.backup())),"preview zero write");s.merge(fixture,empty);JSONObject source=fixture.getJSONArray("sources").getJSONObject(0);check(PersonMethodModel.canonical(source).equals(PersonMethodModel.canonical(s.get("sources",source.getString("id")))),"CursorWindow full mixed-Unicode long row");s.close();s=new PersonMethodStore(c,name);check(PersonMethodModel.canonical(s.backup()).equals(PersonMethodModel.canonical(fixture)),"reopen all full rows");JSONObject newSubject=subject("new","new@1");s.append(newSubject,new JSONObject());check(s.get("subjects","new@1").getString("displayName").equals("同名作者"),"first empty baseline save");JSONObject next=new JSONObject(newSubject.toString()).put("id","new@2").put("parentId","new@1");s.append(next,newSubject);final PersonMethodStore current=s;rejects(()->current.append(new JSONObject(next.toString()).put("id","new@stale"),newSubject),"stale append no overwrite");JSONObject snapshot=s.backup();s.append(subject("other","other@1"),new JSONObject());rejects(()->current.merge(fixture,snapshot),"stale merge refusal");return "PersonMethod Android store PASS "+count;}finally{s.close();c.deleteDatabase(name);}}
 private static android.widget.Button button(android.view.View view,String text){if(view instanceof android.widget.Button&&text.equals(((android.widget.Button)view).getText().toString()))return (android.widget.Button)view;if(view instanceof android.view.ViewGroup){android.view.ViewGroup g=(android.view.ViewGroup)view;for(int i=0;i<g.getChildCount();i++){android.widget.Button b=button(g.getChildAt(i),text);if(b!=null)return b;}}return null;}
 private static void click(PersonMethodScreen screen,String text){android.widget.Button b=button(screen,text);check(b!=null,"button available "+text);b.performClick();}
 private static void field(PersonMethodScreen screen,String name,String text){((android.widget.EditText)screen.findViewWithTag("pm_"+name)).setText(text);}
 static String runScreen(Context c)throws Exception{count=0;String name="person-method-ui-"+System.nanoTime()+".sqlite";PersonMethodStore store=new PersonMethodStore(c,name);java.util.List<JSONObject> current=new java.util.ArrayList<>();JSONObject original=new JSONObject().put("id","external-doc").put("text","研究😀外部资料");JSONObject external=PersonMethodModel.version("native","docs","external-doc",original);current.add(external);int[] opened={0};PersonMethodScreen[] restored={null};PersonMethodScreen screen=new PersonMethodScreen(c,store,()->{JSONArray all=new JSONArray();for(JSONObject r:current)all.put(r);return all;},ref->{opened[0]++;check(PersonMethodModel.canonical(ref).equals(PersonMethodModel.canonical(external)),"exact source version passed");throw new Exception("target draft protected");});try{field(screen,"displayName","首个对象");field(screen,"platform","人工资料");click(screen,"保存新版本");check(store.backup().getJSONArray("subjects").length()==1,"UI initial empty baseline saved");JSONObject subject=store.backup().getJSONArray("subjects").getJSONObject(0);((android.widget.Spinner)screen.findViewWithTag("pmMode")).setSelection(1);click(screen,"新建");field(screen,"title","手工资料");field(screen,"text","研究😀原文尾部");field(screen,"sourceUrl","https://example.org/source");click(screen,"保存新版本");check(store.backup().getJSONArray("sources").length()==1,"UI source created");check(store.backup().getJSONArray("sources").getJSONObject(0).getJSONObject("legacyOriginal").getString("sourceUrl").equals("https://example.org/source"),"source provenance saved");((android.widget.Spinner)screen.findViewWithTag("pmMode")).setSelection(2);click(screen,"新建");for(String k:new String[]{"title","versionLabel","conditions","steps","evidenceQuote","counterexamples","invalidations"})field(screen,k,k.equals("evidenceQuote")?"研究😀":"人工 "+k);android.widget.Spinner refs=(android.widget.Spinner)screen.findViewWithTag("pmRefPicker");refs.setSelection(refs.getCount()-1);click(screen,"关联完整来源版本");click(screen,"保存新版本");check(store.backup().getJSONArray("methods").length()==1,"UI method saved");JSONObject method=store.backup().getJSONArray("methods").getJSONObject(0);check(PersonMethodModel.canonical(method.getJSONObject("subjectRef").getJSONObject("originalRecord")).equals(PersonMethodModel.canonical(subject)),"UI subject exact snapshot");click(screen,"读取关联的冻结原文");click(screen,"定位来源");check(opened[0]==1,"opener rejection contained");current.clear();current.add(PersonMethodModel.version("native","docs","external-doc",new JSONObject(original.toString()).put("text","changed")));click(screen,"定位来源");check(opened[0]==1,"changed source location refused");click(screen,"返回编辑");field(screen,"conditions","未保存条件");screen.setDarkTheme(true);screen.setDarkTheme(false);android.os.Bundle marker=screen.saveState();PersonMethodScreen reopened=new PersonMethodScreen(c,store,()->new JSONArray(),ref->{});restored[0]=reopened;reopened.restoreState(marker);check(((android.widget.EditText)reopened.findViewWithTag("pm_conditions")).getText().toString().equals("未保存条件"),"draft reopen intact");JSONObject next=new JSONObject(method.toString()).put("id","m@external").put("parentId",method.getString("id"));store.append(next,method);click(reopened,"保存新版本");check(store.backup().getJSONArray("methods").length()==2,"stale UI save no row");check(((android.widget.EditText)reopened.findViewWithTag("pm_conditions")).getText().toString().equals("未保存条件"),"stale UI preserves draft");return "PersonMethod Android UI PASS "+count;}finally{screen.onDetachedFromWindow();if(restored[0]!=null)restored[0].onDetachedFromWindow();store.close();c.deleteDatabase(name);new File(c.getDatabasePath(name).getAbsolutePath()+".person-method-view.json").delete();}}
 static String runLargeReader(Context c,String fixtureText)throws Exception{count=0;String name="person-method-reader-"+System.nanoTime()+".sqlite";PersonMethodStore store=new PersonMethodStore(c,name);PersonMethodScreen screen=new PersonMethodScreen(c,store,()->new JSONArray(),ref->{});try{JSONObject fixture=PersonMethodModel.decode(fixtureText);screen.previewImport(fixtureText);check(store.backup().getJSONArray("sources").length()==0,"reader preview zero writes");screen.confirmImport();JSONObject source=fixture.getJSONArray("sources").getJSONObject(0);((android.widget.Spinner)screen.findViewWithTag("pmMode")).setSelection(1);click(screen,"列表");click(screen,source.getString("title")+" · "+source.getString("id"));check(((android.widget.EditText)screen.findViewWithTag("pm_text")).getText().toString().equals(source.getString("text")),"full source editor load, no clipping");click(screen,"完整原记录");String read=((android.widget.TextView)screen.findViewWithTag("pmOriginal")).getText().toString();check(read.contains(source.getString("text")),"reader contains complete >2MiB original body");check(read.contains("未知必须保留")&&read.contains("评论原文"),"reader retains unknown and comment archive");android.os.Bundle state=screen.saveState();check(state.keySet().size()==1&&state.getString("stateFile").length()<1000,"Bundle carries file marker, not huge source");return "PersonMethod Android large-reader PASS "+count;}finally{screen.onDetachedFromWindow();store.close();c.deleteDatabase(name);new File(c.getDatabasePath(name).getAbsolutePath()+".person-method-view.json").delete();}}
 public static void main(String[] args)throws Exception{count=0;JSONObject f=fixture(args[0]);runModel(f);if(args.length>1)Files.write(Paths.get(args[1]),f.toString().getBytes(StandardCharsets.UTF_8));System.out.println("PersonMethod Java model/cross PASS "+count);}
}
